PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE manifests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  reference TEXT NOT NULL UNIQUE,
  supplier TEXT NOT NULL,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'open',  
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  closed_at DATETIME
, organisation_id INTEGER NOT NULL DEFAULT 1, created_by_user_id INTEGER);
CREATE TABLE expected_devices (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  manifest_id INTEGER NOT NULL,
  oem TEXT,
  condition TEXT,            
  description TEXT,          
  grade TEXT,                
  model_no TEXT,             
  imei TEXT NOT NULL,
  unit_cost REAL,
  sku TEXT,                  
  status TEXT NOT NULL DEFAULT 'pending', 
  received_at DATETIME,
  received_device_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, capacity TEXT, color TEXT, organisation_id INTEGER NOT NULL DEFAULT 1, currency TEXT, vat_type TEXT,
  FOREIGN KEY (manifest_id) REFERENCES manifests(id) ON DELETE CASCADE
);
CREATE TABLE sku_catalog (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT NOT NULL UNIQUE,
  brand TEXT NOT NULL,
  model TEXT NOT NULL,
  capacity TEXT,
  color TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, grade TEXT, organisation_id INTEGER NOT NULL DEFAULT 1);
CREATE TABLE print_jobs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  received_device_id INTEGER NOT NULL,
  printer TEXT NOT NULL DEFAULT 'DYMO LabelWriter 450',
  payload_json TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued', 
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  sent_at DATETIME, organisation_id INTEGER NOT NULL DEFAULT 1, created_by_user_id INTEGER,
  FOREIGN KEY (received_device_id) REFERENCES received_devices(id) ON DELETE CASCADE
);
CREATE TABLE scan_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  manifest_id INTEGER,
  imei TEXT NOT NULL,
  outcome TEXT NOT NULL,  
  message TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, organisation_id INTEGER NOT NULL DEFAULT 1, user_id INTEGER);
CREATE TABLE grade_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  received_device_id INTEGER NOT NULL,
  imei TEXT NOT NULL,
  old_grade TEXT,
  new_grade TEXT NOT NULL,
  actor TEXT NOT NULL DEFAULT 'operator',
  reason TEXT,
  bulk_id TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, organisation_id INTEGER NOT NULL DEFAULT 1, user_id INTEGER,
  FOREIGN KEY (received_device_id) REFERENCES received_devices(id) ON DELETE CASCADE
);
CREATE TABLE organisations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  slug TEXT UNIQUE,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL UNIQUE,
  name TEXT,
  role TEXT NOT NULL DEFAULT 'operator' CHECK (role IN ('operator', 'manager', 'admin')),
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, password_hash TEXT);
CREATE TABLE suppliers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  name TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE webhooks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  url TEXT NOT NULL,
  secret TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "app_settings" (
  organisation_id INTEGER PRIMARY KEY REFERENCES organisations(id),
  print_mode TEXT NOT NULL DEFAULT 'browser',
  printnode_api_key TEXT,
  printnode_printer_id_large INTEGER,
  printnode_printer_id_small INTEGER,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "received_devices" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL DEFAULT 1 REFERENCES organisations(id),
  uuid TEXT NOT NULL UNIQUE,
  imei TEXT NOT NULL UNIQUE,
  sku TEXT NOT NULL,
  brand TEXT,
  model TEXT,
  capacity TEXT,
  color TEXT,
  grade TEXT NOT NULL DEFAULT 'UG'
    CHECK (grade IN ('A','B','C','UG')),
  source TEXT NOT NULL
    CHECK (source IN ('manifest','unreconciled','manual')),
  manifest_id INTEGER,
  expected_device_id INTEGER,
  status TEXT NOT NULL DEFAULT 'RECEIVED'
    CHECK (status IN (
      'RECEIVED','SORTING','ACTIVE_INVENTORY','IN_HOUSE_REPAIR',
      'READY_FOR_EXPORT','IN_EXPORT_CONSIGNMENT','EXPORTED_UNDER_OPR',
      'RETURNED_UNDER_OPR','SOLD','REJECTED'
    )),
  label_printed_at DATETIME,
  notes TEXT,
  created_by_user_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME, buy_price REAL, currency TEXT NOT NULL DEFAULT 'GBP', vat_type TEXT, supplier_id INTEGER REFERENCES suppliers(id),
  FOREIGN KEY (manifest_id)        REFERENCES manifests(id)        ON DELETE SET NULL,
  FOREIGN KEY (expected_device_id) REFERENCES expected_devices(id) ON DELETE SET NULL
);
CREATE TABLE device_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  device_id INTEGER REFERENCES received_devices(id),
  event_type TEXT NOT NULL,        
  from_status TEXT,
  to_status TEXT,
  user_id INTEGER REFERENCES users(id),
  reference TEXT,                  
  metadata TEXT,                   
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE opr_authorisations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  holder_name TEXT NOT NULL,                
  eori TEXT NOT NULL,                       
  cds_number TEXT NOT NULL,                 
  op_authorisation_number TEXT,                        
  valid_from DATE NOT NULL,
  valid_to DATE NOT NULL,
  supervising_office_name TEXT,             
  supervising_office_code TEXT,             
  commodity_scope TEXT,                     
  commodity_codes TEXT,                     
  rate_of_yield TEXT NOT NULL DEFAULT '1:1',
  discharge_period_months INTEGER NOT NULL DEFAULT 6,
  notes TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME
, prealert_email TEXT, prealert_cutoff TEXT);
CREATE TABLE shipments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  reference TEXT NOT NULL,                  
  direction TEXT NOT NULL CHECK (direction IN ('export','import')),
  shipment_type TEXT NOT NULL DEFAULT 'OPR_REPAIR'
    CHECK (shipment_type IN ('OPR_REPAIR')),
  status TEXT NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT','FINALISED','CANCELLED')),  
  authorisation_id INTEGER NOT NULL REFERENCES opr_authorisations(id),
  procedure_code TEXT NOT NULL,             
  additional_procedure_code TEXT,           
  consignee_name TEXT,                      
  consignee_address TEXT,
  carrier TEXT,                             
  carrier_account TEXT,
  incoterm TEXT,                            
  currency TEXT NOT NULL DEFAULT 'GBP',     
  ship_date DATE,
  
  related_export_shipment_id INTEGER REFERENCES shipments(id),
  export_mrn TEXT,                          
  notes TEXT,
  created_by_user_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME
, ducr TEXT, ead_mrn TEXT, finalised_at DATETIME, finalised_by_user_id INTEGER, repair_cost REAL, repair_cost_currency TEXT, customs_exchange_rate REAL, duty_rate_pct REAL, import_mrn TEXT, mucr TEXT, reconciled_value_gbp REAL, customs_entry_ref TEXT, vat_evidence_ref TEXT, repair_cost_confirmed_at DATETIME, repair_cost_confirmed_by_user_id INTEGER);
CREATE TABLE shipment_lines (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL REFERENCES organisations(id),
  shipment_id INTEGER NOT NULL REFERENCES shipments(id) ON DELETE CASCADE,
  received_device_id INTEGER NOT NULL REFERENCES received_devices(id),
  
  imei TEXT NOT NULL,
  sku TEXT,
  brand TEXT,
  model TEXT,
  capacity TEXT,
  color TEXT,
  grade TEXT,
  unit_value REAL NOT NULL,                 
  currency TEXT NOT NULL DEFAULT 'GBP',
  added_by_user_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sent_emails (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL,
  shipment_id INTEGER NOT NULL,
  kind TEXT NOT NULL,                
  to_email TEXT NOT NULL,
  subject TEXT NOT NULL,
  provider TEXT NOT NULL DEFAULT 'gmail',
  provider_message_id TEXT,          
  status TEXT NOT NULL,              
  error TEXT,                        
  user_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (shipment_id) REFERENCES shipments(id)
);
CREATE TABLE shipment_value_deltas (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL,
  shipment_id INTEGER NOT NULL,
  old_value_gbp REAL NOT NULL,     
  new_value_gbp REAL NOT NULL,
  difference_gbp REAL NOT NULL,    
  note TEXT,
  user_id INTEGER,                 
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (shipment_id) REFERENCES shipments(id)
);
CREATE TABLE shipment_replies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  organisation_id INTEGER NOT NULL,
  shipment_id INTEGER NOT NULL,
  from_mailbox TEXT NOT NULL,
  summary TEXT NOT NULL,
  received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  logged_by_user_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (shipment_id) REFERENCES shipments(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_expected_manifest ON expected_devices(manifest_id);
CREATE INDEX idx_expected_imei ON expected_devices(imei);
CREATE INDEX idx_expected_status ON expected_devices(status);
CREATE INDEX idx_sku_brand_model ON sku_catalog(brand, model);
CREATE INDEX idx_print_status ON print_jobs(status);
CREATE INDEX idx_scan_manifest ON scan_events(manifest_id);
CREATE INDEX idx_grade_audit_device ON grade_audit(received_device_id);
CREATE INDEX idx_grade_audit_bulk   ON grade_audit(bulk_id);
CREATE INDEX idx_sku_catalog_lookup
  ON sku_catalog(model, capacity, color, grade);
CREATE INDEX idx_users_org ON users(organisation_id);
CREATE INDEX idx_suppliers_org ON suppliers(organisation_id);
CREATE INDEX idx_webhooks_org ON webhooks(organisation_id);
CREATE INDEX idx_manifests_org        ON manifests(organisation_id);
CREATE INDEX idx_expected_org         ON expected_devices(organisation_id);
CREATE INDEX idx_sku_catalog_org      ON sku_catalog(organisation_id);
CREATE INDEX idx_print_jobs_org       ON print_jobs(organisation_id);
CREATE INDEX idx_scan_events_org      ON scan_events(organisation_id);
CREATE INDEX idx_grade_audit_org      ON grade_audit(organisation_id);
CREATE INDEX idx_received_imei     ON received_devices(imei);
CREATE INDEX idx_received_sku      ON received_devices(sku);
CREATE INDEX idx_received_manifest ON received_devices(manifest_id);
CREATE INDEX idx_received_org      ON received_devices(organisation_id);
CREATE INDEX idx_received_status   ON received_devices(status);
CREATE INDEX idx_device_events_device ON device_events(device_id);
CREATE INDEX idx_device_events_org    ON device_events(organisation_id);
CREATE INDEX idx_device_events_type   ON device_events(event_type);
CREATE INDEX idx_received_supplier ON received_devices(supplier_id);
CREATE INDEX idx_opr_auth_org ON opr_authorisations(organisation_id);
CREATE UNIQUE INDEX idx_opr_auth_cds ON opr_authorisations(organisation_id, cds_number);
CREATE INDEX idx_shipments_org ON shipments(organisation_id);
CREATE INDEX idx_shipments_auth ON shipments(authorisation_id);
CREATE UNIQUE INDEX idx_shipments_org_ref ON shipments(organisation_id, reference);
CREATE INDEX idx_shipment_lines_shipment ON shipment_lines(shipment_id);
CREATE INDEX idx_shipment_lines_device ON shipment_lines(received_device_id);
CREATE UNIQUE INDEX idx_shipment_lines_unique ON shipment_lines(shipment_id, received_device_id);
CREATE INDEX idx_sent_emails_shipment ON sent_emails(shipment_id);
CREATE INDEX idx_sent_emails_org ON sent_emails(organisation_id);
CREATE INDEX idx_shipment_value_deltas_shipment ON shipment_value_deltas(shipment_id);
CREATE INDEX idx_shipment_value_deltas_org ON shipment_value_deltas(organisation_id);
CREATE INDEX idx_shipment_replies_shipment ON shipment_replies(shipment_id);
CREATE INDEX idx_shipment_replies_org ON shipment_replies(organisation_id);